import random, math

def eval_d1(mode, trials=40000):
    # Employees 0..17: d1-1 (18)
    # Employees 18..31: d1-2 (14)
    # Employees 32..39: Eng (8, 0 docs on d1)
    c_leaks = 0
    tot_leaks = 0
    for _ in range(trials):
        mole = random.randrange(40)
        held = []
        if mole < 18:
            held.append((1, False, 1.0))
        elif mole < 32:
            held.append((1, False, 1.0))

        if mode == "20_20":
            if mole < 20:
                held.append((1, True, 1.0 - 20/40))
            else:
                held.append((1, True, 1.0 - 20/40))
        elif mode == "20_12_non_eng":
            if mole < 20:
                held.append((1, True, 1.0 - 20/40))
            elif mole < 32:
                held.append((1, True, 1.0 - 12/40))
        elif mode == "18_14_non_eng":
            if mole < 18:
                held.append((1, True, 1.0 - 18/40))
            elif mole < 32:
                held.append((1, True, 1.0 - 14/40))
        elif mode == "none":
            pass

        leaked_c = False
        for day in [1, 2, 3]:
            if day > 1:
                for _ in range(random.choice([2,3,4])):
                    if random.random() < 0.4:
                        held.append((day, False, 1.0))
            elig = [i for i, (d, ic, w) in enumerate(held) if day - d < 3]
            if elig and random.random() < 0.65:
                tot_leaks += 1
                tw = sum(held[i][2] for i in elig)
                r = random.random() * tw
                acc = 0.0
                picked = elig[-1]
                for i in elig:
                    acc += held[i][2]
                    if r <= acc:
                        picked = i
                        break
                if held[picked][1]:
                    leaked_c = True
                held.pop(picked)
        if leaked_c:
            c_leaks += 1
    c_cost = 0.0 if mode == "none" else 0.02
    v_loss = c_cost + (tot_leaks / trials) * 0.05
    print(f"{mode:15s}: P(canary_leak)={c_leaks/trials:.3f}, avg_leaks={tot_leaks/trials:.3f}, E[V_loss_d1_3]={v_loss:.4f}")

for m in ["none", "20_20", "20_12_non_eng", "18_14_non_eng"]:
    eval_d1(m)
'
